CREATE TYPE "SubtitleStatus" AS ENUM ('PENDING', 'TRANSCRIBING', 'READY', 'NO_SPEECH', 'FAILED');
CREATE TYPE "FinalQaStatus" AS ENUM ('PENDING', 'CHECKING', 'PASSED', 'ISSUES', 'FAILED');
ALTER TABLE "FinalVideo" ADD COLUMN "baseFileUrl" TEXT, ADD COLUMN "baseStorageKey" TEXT, ADD COLUMN "baseDuration" DOUBLE PRECISION, ADD COLUMN "enhancedFileUrl" TEXT, ADD COLUMN "enhancedStorageKey" TEXT, ADD COLUMN "enhancedDuration" DOUBLE PRECISION, ADD COLUMN "enhancedFileSize" INTEGER;
CREATE TABLE "VideoRenderSettings" ("id" TEXT NOT NULL, "projectId" TEXT NOT NULL, "subtitleEnabled" BOOLEAN NOT NULL DEFAULT true, "bgmEnabled" BOOLEAN NOT NULL DEFAULT false, "bgmTrackId" TEXT, "bgmVolume" DOUBLE PRECISION NOT NULL DEFAULT 0.14, "originalAudioVolume" DOUBLE PRECISION NOT NULL DEFAULT 1, "version" INTEGER NOT NULL DEFAULT 1, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "VideoRenderSettings_pkey" PRIMARY KEY ("id"));
CREATE TABLE "BgmTrack" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "fileUrl" TEXT NOT NULL, "storageKey" TEXT NOT NULL, "duration" DOUBLE PRECISION NOT NULL, "category" TEXT NOT NULL, "licenseNote" TEXT NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "BgmTrack_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SubtitleTrack" ("id" TEXT NOT NULL, "projectId" TEXT NOT NULL, "finalVideoId" TEXT NOT NULL, "status" "SubtitleStatus" NOT NULL DEFAULT 'PENDING', "language" TEXT, "segments" JSONB, "provider" TEXT, "model" TEXT, "transcriptionDurationMs" INTEGER, "errorMessage" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "SubtitleTrack_pkey" PRIMARY KEY ("id"));
CREATE TABLE "FinalVideoQA" ("id" TEXT NOT NULL, "finalVideoId" TEXT NOT NULL, "status" "FinalQaStatus" NOT NULL DEFAULT 'PENDING', "passed" BOOLEAN, "criticalIssues" TEXT[] DEFAULT ARRAY[]::TEXT[], "mainIssue" TEXT, "advice" TEXT, "confidence" DOUBLE PRECISION, "provider" TEXT, "model" TEXT, "programChecks" JSONB, "finalQaDurationMs" INTEGER, "errorMessage" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "FinalVideoQA_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "VideoRenderSettings_projectId_key" ON "VideoRenderSettings"("projectId");
CREATE UNIQUE INDEX "BgmTrack_storageKey_key" ON "BgmTrack"("storageKey");
CREATE UNIQUE INDEX "SubtitleTrack_finalVideoId_key" ON "SubtitleTrack"("finalVideoId");
CREATE UNIQUE INDEX "FinalVideoQA_finalVideoId_key" ON "FinalVideoQA"("finalVideoId");
ALTER TABLE "VideoRenderSettings" ADD CONSTRAINT "VideoRenderSettings_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "VideoRenderSettings" ADD CONSTRAINT "VideoRenderSettings_bgmTrackId_fkey" FOREIGN KEY ("bgmTrackId") REFERENCES "BgmTrack"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "SubtitleTrack" ADD CONSTRAINT "SubtitleTrack_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "SubtitleTrack" ADD CONSTRAINT "SubtitleTrack_finalVideoId_fkey" FOREIGN KEY ("finalVideoId") REFERENCES "FinalVideo"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "FinalVideoQA" ADD CONSTRAINT "FinalVideoQA_finalVideoId_fkey" FOREIGN KEY ("finalVideoId") REFERENCES "FinalVideo"("id") ON DELETE CASCADE ON UPDATE CASCADE;
